      const k = this.kit('k_ring', x, y, r * 2.2, GROUND + 2);
      if (k) { const kx = k.scaleX, ky = (r * 2.2 * SQUASH) / k.height; this.piece(k, life, (u, o) => o.setScale(kx * lerp(0.2, 1, out3(u)), ky * lerp(0.2, 1, out3(u))).setAlpha(1 - u * u), delay); return; }
