    const cards = Array.from({ length: 5 }, () => this.onBody(s.add.image(0, 0, this.BK).setScale(this.u * 0.27).setVisible(false), r.attackerId));
    const glow = this.onBody(this.glow(0, 0, 50), r.attackerId); let maxed = false;
