        if (fuse) fuse.setPosition(p.x, p.y - H * 0.75 - 16).setDepth(p.d + 5).setAlpha(Math.floor(t / Math.max(50, 160 - u * 120)) % 2 ? 1 : 0.45).setAngle(t * 0.25);
