    this.add((t) => { if (t < T.startup) return true; this.stroke('s_vault', o0.x + r.aim.x * 110, o0.y + r.aim.y * 110 - o0.z - 72, 180, side, T.active + 240, o0.y + 2, 0, 0.5, 0.5); return false; });
