  mx?: (u: number) => number; my?: (u: number) => number;
  follow?: () => Pt | null; dz?: number;
  run?: CastRun;
  alive?: () => boolean;
  /** sits on this fighter's body (her bow): PVP 3D draws it flat with the painted body (ON_BODY) */
