          this.spr({ name: 'sn-flash', w: 70, life: 120, delay: T.startup, tint: 0xece6dc, follow: this.at(r.attackerId, side, 62, 78), dz: 5, glow: 0.2, run: r,
            sx: kf([0, 0.6], [0.35, 1.05, out3]), sy: kf([0, 0.6], [0.35, 1.05, out3]), a: kf([0, 1], [1, 0, inQ]) });
