      if (big) this.spr({ name: 'sn-ring', x, y, depth: TOP + 4, w: 70, life: 200, tint: ROUND, glow: 0.3, sx: kf([0, 0.4], [1, 1.5, out3]), sy: kf([0, 0.4], [1, 1.5, out3]), a: kf([0, 0.9], [1, 0, inQ]) });
