        this.spr({ name: 'dust', x: fx, y: fy + 4, oy: 0.85, depth: fy + 1, w: 140, life: 520, sx: kf([0, 0.5], [1, 1.4, out3]), a: kf([0, 0.85], [1, 0, inQ]) });
