import Phaser from 'phaser';
import { HUD } from '../config/layout';
import GATE from '../data/world-goldgate.json';
import { WORLD_OBJECTS, type Pt, type WorldObject } from './WorldGeometry';

/** The Sun Gate (tools/world/goldgate.py): a golden gate with short stone walls across the terrace right of Ivy Heights. Closed (locked with its
 *  little sun) until the sun over Sunfall Pass has been crossed — the way on is up the stairs and over the clouds — then
 *  open for good. Drawn in narrow columns, each at the depth of the gate's foot line where it stands (whoever is in front
 *  of a part of it is drawn over that part), its posts and doors solid. */
const COLS = 32;
const RAIL_DEPTH = 356.5;   // over Ivy Heights' floor and whoever stands up there (their band reaches ~355 by the gate's walls)
const BACK = 48;     // how deep its walls, pillars and doors stand behind their painted base (world px)

export const SUN_GATE = GATE as unknown as { img: { closed: string; open: string }; x: number; y: number; w: number; h: number; sx: number; sy: number; back: [number, number]; front: [number, number]; doors: [number, number]; foot: [number, number][];
  rail: { img: string; x: number; y: number; w: number; h: number; sx: number; sy: number; x0: number; x1: number } };
/** The gate line's x at depth y (its foot line, extended). */
export const sunGateX = (y: number): number => {
  const [bx, by] = SUN_GATE.back, [fx, fy] = SUN_GATE.front;
  return bx + ((fx - bx) * (y - by)) / (fy - by);
};

/** Its painted base's depth at x (between the measured columns; its ends held level). */
const lineY = (x: number): number => {
  const f = SUN_GATE.foot;
  if (x <= f[0][0]) return f[0][1];
  for (let i = 1; i < f.length; i++) if (x <= f[i][0]) return f[i - 1][1] + ((f[i][1] - f[i - 1][1]) * (x - f[i - 1][0])) / (f[i][0] - f[i - 1][0]);
  return f[f.length - 1][1];
};
/** Its footprint along its base from x0 to x1: from the painted base back by its thickness (whoever stands in front of
 *  it stands before its face, never in it), a strip per measured column; its ends sealed (ext: past the back / front). */
const strips = (id: string, x0: number, x1: number, ext0 = 0, ext1 = 0): WorldObject[] => {
  const f = SUN_GATE.foot.filter((p) => p[0] >= x0 - 1e-6 && p[0] <= x1 + 1e-6), out: WorldObject[] = [];
  for (let i = 0; i + 1 < f.length; i++) {
    const [ax, ay] = f[i], [bx, by] = f[i + 1], top = Math.min(ay, by) - BACK - (i === 0 ? ext0 : 0), bot = Math.max(ay, by) + 2 + (i + 2 === f.length ? ext1 : 0);
    out.push(solid(`${id}-${i}`, [[ax - 1, top], [bx + 1, top], [bx + 1, bot], [ax - 1, bot]]));
  }
  return out;
};
const solid = (id: string, foot: Pt[]): WorldObject => ({ id, footprint: foot, height: 4000, cover: 'hard', occluder: [], frontY: Math.max(...foot.map((p) => p[1])) + 1 });

export class SunGate {
  private cols: Phaser.GameObjects.Image[] = [];
  private rail?: Phaser.GameObjects.Image;
  private isOpen: boolean;

  /** `pictures`: its painting (the 3D world models the gate itself and keeps only its footprint and its logic). */
  constructor(private scene: Phaser.Scene, open: boolean, private pictures = true) {
    this.isOpen = open;
    const load = (k: 'closed' | 'open') => `sun-gate-${k}`;
    const make = () => {
      if (!scene.textures.exists(load('closed')) || !scene.textures.exists(load('open')) || !scene.textures.exists('sun-gate-rail') || this.cols.length) return;
      // the balustrade on Ivy Heights' corner above it: on that floor's front edge, before whoever stands up there
      const r = SUN_GATE.rail;
      this.rail = scene.add.image(r.x, r.y, 'sun-gate-rail').setOrigin(0, 0).setScale(r.sx, r.sy).setDepth(RAIL_DEPTH);
      const cw = Math.ceil(SUN_GATE.w / COLS);
      for (let i = 0; i < COLS; i++) {
        const x0 = i * cw, mid = SUN_GATE.x + (x0 + cw / 2) * SUN_GATE.sx;
        // its depth: the foot line where this column stands (its back end behind whoever is in front, its front end over)
        // (the deepest base near it: a pillar standing out in front covers whoever stands beside it, behind its face)
        const near = SUN_GATE.foot.filter((p) => Math.abs(p[0] - mid) <= 36), y = near.length ? Math.max(...near.map((p) => p[1])) : lineY(mid);
        this.cols.push(scene.add.image(SUN_GATE.x, SUN_GATE.y, load(this.isOpen ? 'open' : 'closed')).setOrigin(0, 0).setScale(SUN_GATE.sx, SUN_GATE.sy).setCrop(x0, 0, cw, SUN_GATE.h).setDepth(y + 0.5));
      }
    };
    if (!this.pictures) { this.solids(); return; }
    for (const k of ['closed', 'open'] as const) if (!scene.textures.exists(load(k))) scene.load.image(load(k), SUN_GATE.img[k]);
    if (!scene.textures.exists('sun-gate-rail')) scene.load.image('sun-gate-rail', SUN_GATE.rail.img);
    if (scene.textures.exists(load('closed')) && scene.textures.exists(load('open')) && scene.textures.exists('sun-gate-rail')) make();
    else { scene.load.on(Phaser.Loader.Events.COMPLETE, make); if (!scene.load.isLoading()) scene.load.start(); }
    this.solids();
  }

  get open(): boolean { return this.isOpen; }

  /** The inscription over the closed gate (a parchment plaque), shown while someone stands before it. */
  private plaque?: Phaser.GameObjects.Container;
  private plaqueA = 0;
  near(x: number, y: number, z: number, ms: number): void {
    const by = Phaser.Math.Clamp(y, SUN_GATE.foot[0][1], SUN_GATE.foot[SUN_GATE.foot.length - 1][1]);
    const close = !this.isOpen && z < 120 && Math.abs(x - sunGateX(by)) < 400 && x < sunGateX(by) + 20;
    this.plaqueA += ((close ? 1 : 0) - this.plaqueA) * Math.min(1, ms / 140); if (!close && this.plaqueA < 0.02) this.plaqueA = 0;
    if (this.plaqueA <= 0) { this.plaque?.setVisible(false); return; }
    if (!this.plaque) this.plaque = this.makePlaque();
    this.plaque?.setVisible(true).setAlpha(this.plaqueA);
  }

  private makePlaque(): Phaser.GameObjects.Container {
    const sc = this.scene, PAD = { x: 24, y: 16 };
    const title = sc.add.text(0, 0, 'THE SUN GATE', { fontFamily: 'Cinzel, Georgia, serif', fontSize: '18px', fontStyle: '700', color: '#7a4a0c', resolution: 2 }).setOrigin(0.5, 0);
    const body = sc.add.text(0, 0, 'Sealed by the Masters against the Curse of the east.\nIt opens only for one who has crossed the sun.', {
      fontFamily: HUD.bodyFont, fontSize: '14px', color: '#33230c', align: 'center', lineSpacing: 5, resolution: 2 }).setOrigin(0.5, 0);
    const w = Math.max(title.width, body.width) + PAD.x * 2, h = title.height + 8 + body.height + PAD.y * 2;
    // a parchment plaque: warm paper, a thin gold rim and a soft shadow
    const g = sc.add.graphics();
    g.fillStyle(0x000000, 0.28).fillRoundedRect(-w / 2 + 3, 5, w, h, 12);
    g.fillStyle(0xf6e7c4, 0.97).fillRoundedRect(-w / 2, 0, w, h, 12);
    g.lineStyle(2, 0xc9a24a, 1).strokeRoundedRect(-w / 2 + 1, 1, w - 2, h - 2, 11);
    g.lineStyle(1, 0xe9cf8a, 1).strokeRoundedRect(-w / 2 + 5, 5, w - 10, h - 10, 8);
    title.setPosition(0, PAD.y); body.setPosition(0, PAD.y + title.height + 8);
    const dx = (SUN_GATE.doors[0] + SUN_GATE.doors[1]) / 2 + 20;
    return sc.add.container(Math.round(dx), Math.round(SUN_GATE.y - h + 30), [g, title, body]).setDepth(1e6 - 1).setAlpha(0);
  }

  /** The gate unlocked: its doors swing open (a flash of warm light), and the way is free from now on. */
  unlock(): void {
    if (this.isOpen) return;
    this.isOpen = true; this.solids(); this.plaque?.setVisible(false);
    for (const c of this.cols) c.setTexture('sun-gate-open');
    const dx = (SUN_GATE.doors[0] + SUN_GATE.doors[1]) / 2;
    const flash = this.scene.add.ellipse(dx, lineY(dx) - 110, 200, 240, 0xffe2a0, 0)
      .setDepth(lineY(dx) + 2).setBlendMode(Phaser.BlendModes.ADD);
    this.scene.tweens.add({ targets: flash, alpha: { from: 0, to: 0.75 }, duration: 380, yoyo: true, ease: 'Sine.easeInOut', onComplete: () => flash.destroy() });
  }

  /** Its solid parts in the world: the walls and pillars always, the doors while closed. */
  private solids(): void {
    for (let i = WORLD_OBJECTS.length - 1; i >= 0; i--) if (WORLD_OBJECTS[i].id.startsWith('sun-gate')) WORLD_OBJECTS.splice(i, 1);
    const f = SUN_GATE.foot, x0 = f[0][0], x1 = f[f.length - 1][0], [d0, d1] = SUN_GATE.doors, r = SUN_GATE.rail;
    // the balustrade up on Ivy Heights' front edge: too high to jump over
    WORLD_OBJECTS.push({ ...solid('sun-gate-rail', [[r.x0, 334], [r.x1, 334], [r.x1, 352], [r.x0, 352]]), height: 480 });
    if (!this.isOpen) WORLD_OBJECTS.push(...strips('sun-gate', x0, x1, 30, 40));
    else WORLD_OBJECTS.push(...strips('sun-gate-back', x0, d0 + 26, 30, 0), ...strips('sun-gate-front', d1 - 26, x1, 0, 40));
  }

  destroy(): void {
    for (const c of this.cols) c.destroy(); this.cols = []; this.rail?.destroy(); this.plaque?.destroy();
    for (let i = WORLD_OBJECTS.length - 1; i >= 0; i--) if (WORLD_OBJECTS[i].id.startsWith('sun-gate')) WORLD_OBJECTS.splice(i, 1);
  }
}
