// Open-world monster on the shared combat foundation (same reactions as every fighter: launch, juggle, knockdown,
// getup). Side view: faces left or right. Life (MapleStory's — the rebuild's Phase 8): every ≈1.6 s it stands or walks
// left / right a stretch about its home spot, turning at an edge; it pays you no mind until you hit it (a boss, or a
// monster spawned to fight — the den — sees you and comes) → follows you → strikes (windup / active / recovery) →
// gives up when you run far away and walks home. Dies at 0 HP (drops gold,
// handled by the scene) and comes back at its home spot after a while. Damage and reactions are applied by the scene.
import Phaser from 'phaser';
import { STAGE6 } from '../config/layout';
import { WORLD_OBJECTS, actorDepth, clearLine, footAllowed, supportAt } from './WorldGeometry';
import { CombatBody, Kin, newKin, settleOnBlocks, stepKin } from '../combat/Combat';
import { HitTarget } from '../skills/HitGeometry';
import { NAME_DEPTH } from '../game/ActorView';
import { MobKind, MOB_WALL_X } from './Areas';

const C = STAGE6.enemy;
type Action = keyof typeof C.actions;
/** A hit makes the monster follow the player this long (ms). */
const PROVOKED_MS = 15000;
/** A monster this strong is a boss: hits don't stop its swing. */
const BOSS_HP = 1000;
/** MapleStory's patrol: a choice (stand / walk left / walk right) every ≈1.6 s, walks of this length, this far from home. */
const PATROL = { everyMs: 1600, jitterMs: 600, walk: [50, 140], roam: 170, drift: 18 };
/** A plain hit pushes an ordinary monster back at least this far (px; MapleStory: it gives ground). */
const MIN_KNOCK = 22;
/** The HP bar (and the name tag) after a hit (MapleStory: about two seconds). */
const BAR_MS = 2000;
/** The player up on a block this much higher (px) is still within its blade's reach (beside the block). */
const REACH_UP = 100;
type AIState = 'idle' | 'wander' | 'chase' | 'attack' | 'home' | 'dead';
type Side = 'left' | 'right';
const WIND = 180, ACTIVE = 120, RECOVER = 260; // strike phases (ms), the frame art's timing

export const mobFrameKey = (set: string, dir: Side, action: Action, i: number) => `mob-${set}-${dir}-${action}-${i}`;

export function preloadMonsterFrames(scene: Phaser.Scene, set: string): void {
  for (const dir of ['left', 'right'] as Side[]) {
    for (const [action, n] of Object.entries(C.actions) as [Action, number][]) {
      for (let i = 0; i < n; i++) {
        const key = mobFrameKey(set, dir, action, i);
        if (!scene.textures.exists(key)) scene.load.image(key, `assets/enemy/${set}/${dir}/${action}/${String(i).padStart(2, '0')}.png`);
      }
    }
  }
}

export interface MonsterWorld {
  player: { x: number; y: number; z: number; alive: boolean; /** the floor he stands on (0: the lower floor) */ level?: number; /** his character level (the name tag's colour) */ charLevel?: number };
  now: number;
  /** Feet circle at (x, y) blocked by another actor (the player, another monster). */
  blocked: (self: Monster, x: number, y: number) => boolean;
  onStrikePlayer: (m: Monster, damage: number) => void;
}

export class Monster {
  /** The floor it lives on (0: the lower floor; an upper floor's height): it never walks off it, and sees / fights you only
   *  on the same floor (MapleStory: a monster keeps to its platform). */
  readonly homeZ: number;
  readonly sprite: Phaser.GameObjects.Image;
  private shadow: Phaser.GameObjects.Ellipse;
  /** Its contact shadow (the 3D stage lays its sun shadow from it). */
  get foot(): Phaser.GameObjects.Image { return this.shadow as unknown as Phaser.GameObjects.Image; }
  private bar: Phaser.GameObjects.Graphics;
  readonly kin: Kin;
  readonly body: CombatBody;
  hp: number;
  ai: AIState = 'idle';
  private dir: Side;
  private stateMs = 0;
  private animMs = 0;
  private sinceAttack = Infinity;
  private struck = false;
  private flashLeft = 0;
  private respawnLeft = 0;
  /** Home west of the Temple Gate: never crosses its line (the monsters of the twilight gardens live east of it). */
  private get west(): boolean { return this.home.x < MOB_WALL_X; }
  /** Hit by the player: it keeps after him this long (ms) however far he runs (never past the Temple Gate). */
  private provokedLeft = 0;
  /** Chasing and a block is in the way: it steps around it (up or down the floor) for this long (ms). */
  private detourLeft = 0; private detourDir = 1;
  private moving = false;
  private kdMs = 0;
  private lastNow = 0;
  private wanderTo: { x: number; y: number } | null = null;
  private barShowUntil = -1;
  /** Last attacker x (lean / tumble away from it) and procedural reaction state. */
  hitFromX = 0;
  lastEv: string | null = null;
  private airMs = 0;
  private tumble = 0;
  private pos = { x: 0, y: 0 };
  private deathFade = 1;
  frozen = false;

  /** Sees the player and comes at him (a boss; a monster spawned to fight, the den's); the others wait to be hit. */
  aggressive = false;
  private tag?: Phaser.GameObjects.Text;
  private charLevel = 1;
  private idleFor = PATROL.everyMs;

  constructor(private scene: Phaser.Scene, readonly id: string, readonly kind: MobKind, readonly home: { x: number; y: number }, seed: number) {
    this.kin = newKin(home.x, home.y);
    this.homeZ = supportAt(home.x, home.y, 1e4).z; this.kin.z = this.kin.supportZ = this.homeZ; // an upper floor: it lives up there
    this.body = new CombatBody(this.kin, false);
    this.body.maxHp = kind.hp; this.hp = kind.hp;
    this.dir = seed % 2 ? 'left' : 'right';
    this.idleFor = PATROL.everyMs + ((seed * 7) % 9 - 4) * 140; // (not all in step)
    this.shadow = scene.add.ellipse(home.x, home.y - 2, 36 * kind.scale, 12 * kind.scale, 0x000000, 0.33);
    this.sprite = scene.add.image(home.x, home.y, mobFrameKey(kind.frames, this.dir, 'idle', 0)).setOrigin(C.origin.x, C.origin.y);
    if (kind.tint !== undefined) this.sprite.setTint(kind.tint);
    this.bar = scene.add.graphics();
    this.stateMs = (seed * 977) % 2600; // spread the first wander of a group
    this.sync();
  }

  get x(): number { return this.kin.x; }
  get y(): number { return this.kin.y; }
  get z(): number { return this.kin.z; }
  get alive(): boolean { return this.ai !== 'dead'; }
  get maxHp(): number { return this.kind.hp; }
  get facing(): Side { return this.dir; }
  get name(): string { return this.kind.name; }
  faceToward(x: number): void { if (Math.abs(x - this.kin.x) > 2) this.dir = x < this.kin.x ? 'left' : 'right'; }
  shake(jx: number, jy: number): void { this.sprite.setPosition(this.pos.x + jx, this.pos.y + jy); }

  target(): HitTarget {
    return { id: this.id, kind: 'enemy', x: this.kin.x, y: this.kin.y, z: this.kin.z, radius: C.collisionRadius * this.kind.scale + 4, height: 74 * this.kind.scale, alive: this.alive, invulnerable: this.lastNow < this.body.invulnUntil };
  }

  /** HP change from a confirmed hit (reactions already applied to `body`); true when this hit killed it. */
  damage(dmg: number, now: number): boolean {
    if (!this.alive) return false;
    if (dmg <= 0) return false;   // blocked / no damage: it carries on (its attack is not cancelled)
    this.hp = Math.max(0, this.hp - dmg);
    this.flashLeft = C.hitFlashMs; this.barShowUntil = now + BAR_MS;
    const b = this.body, away = this.hitFromX <= this.kin.x ? 1 : -1;
    if (this.kind.hp < BOSS_HP && !this.kind.boss && b.state === 'hitstun' && now >= b.pinUntil && this.kin.grounded && (!b.push || Math.abs(b.push.vx * b.push.left) < MIN_KNOCK)) b.push = { vx: (away * MIN_KNOCK) / 110, vy: 0, left: 110 }; // it gives ground (MapleStory)
    if (this.kind.hp < BOSS_HP && !this.kind.boss) this.struck = true; // a hit interrupts the pending strike (a boss swings through it)
    if (this.hp <= 0) { this.enter('dead'); this.respawnLeft = this.kind.respawnMs; this.body.push = null; this.deathFade = 1; return true; }
    this.provokedLeft = PROVOKED_MS;
    if ((this.ai === 'attack' && this.kind.hp < BOSS_HP && !this.kind.boss) || this.ai === 'idle' || this.ai === 'wander' || this.ai === 'home') this.enter('chase'); // provoked
    return false;
  }

  private reset(): void {
    const k = this.kin;
    k.x = this.home.x; k.y = this.home.y; k.z = this.homeZ; k.supportZ = this.homeZ; k.vx = 0; k.vy = 0; k.vz = 0; k.grounded = true;
    this.body.reset(); this.body.maxHp = this.kind.hp;
    this.detourLeft = 0; this.wanderTo = null;
    this.hp = this.kind.hp; this.sinceAttack = Infinity; this.provokedLeft = 0; this.flashLeft = 0; this.barShowUntil = -1; this.tag?.setVisible(false);
    this.restoreTint(); this.sprite.setVisible(true).setAlpha(0);
    this.scene.tweens.add({ targets: this.sprite, alpha: 1, duration: 420 }); // fades back in
    this.enter('idle');
  }

  private restoreTint(): void { if (this.kind.tint !== undefined) this.sprite.setTint(this.kind.tint); else this.sprite.clearTint(); }

  update(ms: number, w: MonsterWorld): void {
    this.stateMs += ms; this.animMs += ms; this.sinceAttack += ms; this.provokedLeft = Math.max(0, this.provokedLeft - ms);
    if (this.flashLeft > 0) { this.flashLeft -= ms; if (this.flashLeft <= 0) this.restoreTint(); }
    const now = w.now, b = this.body;
    this.lastNow = now; this.charLevel = w.player.charLevel ?? this.charLevel;
    const dx = w.player.x - this.x, dy = w.player.y - this.y, dist = Math.hypot(dx, dy);
    this.moving = false;
    if (this.ai === 'dead') {
      this.kin.vx = 0; this.kin.vy = 0;
      this.respawnLeft -= ms;
      if (this.stateMs > 900) this.deathFade = Math.max(0, this.deathFade - ms / 500);
      if (this.respawnLeft <= 0 && Math.hypot(w.player.x - this.home.x, w.player.y - this.home.y) > 90 && !w.blocked(this, this.home.x, this.home.y)) this.reset();
    } else if (b.canAct(now) && !b.silenced(now) && !this.frozen) this.think(ms, w, dx, dy, dist);
    else if (b.state === 'free') { this.kin.vx = 0; this.kin.vy = 0; }
    const r = stepKin(this.kin, ms, b.gravityScale(now), (x, y) => (x > MOB_WALL_X && this.west) || w.blocked(this, x, y) || supportAt(x, y, this.kin.z + 1).z < this.homeZ - 1, this.moving && b.state === 'free' && !b.push);
    this.lastBlocked = r.blockedX || r.blockedY;
    settleOnBlocks(this.kin, ms, 0);   // knocked onto a block: onto its top face; beside one: never left half inside it
    if ((this.ai === 'chase' || this.ai === 'home') && this.moving && r.blockedX && this.detourLeft <= 0) {
      // the block ahead: go round it by its nearer end (up or down the floor)
      const ax = this.kin.x + Math.sign(this.kin.vx || 1) * 24, ay = this.kin.y;
      const o = WORLD_OBJECTS.find((q) => { const xs = q.footprint.map((p) => p[0]), ys = q.footprint.map((p) => p[1]); return ax >= Math.min(...xs) - 20 && ax <= Math.max(...xs) + 20 && ay >= Math.min(...ys) - 20 && ay <= Math.max(...ys) + 20; });
      const ys = o ? o.footprint.map((p) => p[1]) : null;
      this.detourDir = ys ? (ay - Math.min(...ys) < Math.max(...ys) - ay ? -1 : 1) : (this.kin.y < 520 ? 1 : -1);
      this.detourLeft = 800;
    }
    else if (this.detourLeft > 0 && r.blockedY) this.detourDir = -this.detourDir; // that way is blocked too: the other way round
    if (this.moving && (r.blockedX || r.blockedY) && this.ai === 'home') this.wanderTo = null; // bumped into something: pick another spot
    if (this.moving && r.blockedX && this.ai === 'wander' && this.wanderTo) { const t = this.wanderTo, back = this.kin.x - (t.x - this.kin.x); this.wanderTo = this.patrolOk(back, this.kin.y) ? { x: back, y: this.kin.y } : null; if (!this.wanderTo) this.enter('idle'); } // an edge / a wall: it turns round (MapleStory)
    const ev = b.update(now, ms, r.landed, r.impactVz);
    if (ev === 'kdImpact') this.kdMs = 0;
    this.lastEv = ev;
    this.airMs = b.state === 'launched' ? this.airMs + ms : 0;
    this.kdMs += ms;
    this.applyFrame();
    this.sync();
  }

  private think(ms: number, w: MonsterWorld, dx: number, dy: number, dist: number): void {
    const K = this.kind, k = this.kin, sp = K.speed * this.body.moveScale(w.now);
    const fromHome = Math.hypot(k.x - this.home.x, k.y - this.home.y);
    const up = (w.player.level ?? 0) - this.homeZ;
    const level = Math.abs(up) < 40 || (up >= 40 && up <= REACH_UP);   // on its floor, or up on a block it can swing at
    const sees = w.player.alive && level && (this.aggressive || this.kind.boss || K.hp >= BOSS_HP || this.provokedLeft > 0) && (w.player.x < MOB_WALL_X + 40 || !this.west) && dist <= K.aggro && (up >= 40 || clearLine(k.x, k.y, w.player.x, w.player.y, 30)); // an ordinary monster pays him no mind until he hits it
    switch (this.ai) {
      case 'idle': case 'wander': {
        if (sees) { this.enter('chase'); break; }
        if (this.ai === 'idle') {
          k.vx = 0; k.vy = 0;
          if (this.stateMs > this.idleFor) { // MapleStory: every ≈1.6 s it stands on, or walks left / right a stretch
            this.idleFor = PATROL.everyMs + (Math.random() - 0.5) * 2 * PATROL.jitterMs;
            const pick = Math.random();
            if (pick < 0.3) { this.stateMs = 0; break; } // stands a while longer
            const toHome = this.home.x - k.x, side = Math.abs(toHome) > PATROL.roam * 0.6 ? Math.sign(toHome) : pick < 0.65 ? -1 : 1; // far out: back toward home
            const len = PATROL.walk[0] + Math.random() * (PATROL.walk[1] - PATROL.walk[0]);
            const y = Math.max(this.home.y - PATROL.drift * 2, Math.min(this.home.y + PATROL.drift * 2, k.y + (Math.random() - 0.5) * 2 * PATROL.drift));
            for (const dir of [side, -side]) { const x = k.x + dir * len; if (this.patrolOk(x, y)) { this.wanderTo = { x, y }; break; } } // that way an edge: the other way
            this.enter(this.wanderTo ? 'wander' : 'idle');
          }
          break;
        }
        const t = this.wanderTo;
        if (!t || Math.hypot(t.x - k.x, t.y - k.y) < 6 || this.stateMs > 4000) { this.wanderTo = null; this.enter('idle'); k.vx = 0; k.vy = 0; break; }
        if (sees) { this.enter('chase'); break; }
        this.walkToward(t.x, t.y, sp * 0.45);
        break;
      }
      case 'chase': {
        const provoked = this.provokedLeft > 0; // hit by him: it follows him wherever he goes, for a while
        if (!w.player.alive || (!provoked && (dist > K.aggro * 1.8 || fromHome > 520)) || (w.player.x > MOB_WALL_X + 60 && this.west) || (!level && !provoked)) { this.provokedLeft = 0; this.enter('home'); break; }  // past the Temple Gate: out of reach
        this.faceToward(w.player.x);
        const reach = K.range + (up >= 40 ? 34 : 0);   // at a block's side: its blade reaches the one standing on top
        if (dist <= reach && Math.abs(dy) < 34 + (up >= 40 ? 30 : 0)) { k.vx = 0; k.vy = 0; if (this.sinceAttack >= K.cooldown && w.player.z < 40 && level) this.startAttack(); break; }
        if (up >= 40 && this.stateMs > 300 && Math.hypot(k.vx, k.vy) > 0 && this.lastBlocked) { k.vx = 0; k.vy = 0; if (this.sinceAttack >= K.cooldown && dist <= reach + 24) this.startAttack(); break; } // pressed against the block under him
        // stand beside the player (side view): the side it is on, at its reach, same depth
        const side = dx > 0 ? -1 : 1, tx = w.player.x + side * K.range * 0.8, ty = w.player.y;
        if (this.detourLeft > 0) { this.detourLeft -= ms; this.walkToward(k.x + Math.sign(dx) * 12, k.y + this.detourDir * 60, sp); break; } // around the block
        this.walkToward(tx, ty, sp);
        break;
      }
      case 'home': {
        if (sees && fromHome < 380) { this.enter('chase'); break; }
        if (fromHome < 10) { this.enter('idle'); k.vx = 0; k.vy = 0; break; }
        if (this.stateMs === ms || fromHome < this.homeBest - 4) { this.homeBest = fromHome; this.homeBestMs = this.stateMs; }
        if (this.stateMs - this.homeBestMs > 2500) { k.x = this.home.x; k.y = this.home.y; k.vx = 0; k.vy = 0; this.hp = this.maxHp; this.enter('idle'); break; } // stuck on the way back: home at once
        if (this.detourLeft > 0) { this.detourLeft -= ms; this.walkToward(k.x + Math.sign(this.home.x - k.x) * 12, k.y + this.detourDir * 60, sp * 0.8); break; } // around the block
        this.walkToward(this.home.x, this.home.y, sp * 0.8);
        if (this.hp < this.maxHp) this.hp = Math.min(this.maxHp, this.hp + ms * 0.02); // catches its breath on the way back
        break;
      }
      case 'attack': {
        k.vx = 0; k.vy = 0;
        if (K.gust && !this.gusted && this.stateMs >= WIND) { this.gusted = true; this.blowGust(); }
        if (!this.struck && this.stateMs >= WIND && this.stateMs < WIND + ACTIVE && this.canHit(w)) { this.struck = true; w.onStrikePlayer(this, K.damage); }
        if (this.stateMs >= WIND + ACTIVE + RECOVER) this.enter(w.player.alive && (dist <= K.aggro * 1.8 || this.provokedLeft > 0) ? 'chase' : 'home');
        break;
      }
      default: break;
    }
  }

  /** A spot it can walk to on patrol: on its own floor, within its roam of home. */
  private patrolOk(x: number, y: number): boolean {
    return Math.abs(x - this.home.x) <= PATROL.roam && footAllowed(x, y, this.homeZ, 14) && supportAt(x, y, this.homeZ + 1).z === this.homeZ;
  }

  private walkToward(x: number, y: number, speed: number): void {
    const k = this.kin, dx = x - k.x, dy = y - k.y, d = Math.hypot(dx, dy);
    if (d < 3) { k.vx = 0; k.vy = 0; return; }
    k.vx = (dx / d) * speed; k.vy = (dy / d) * speed;
    if (Math.abs(dx) > 4) this.dir = dx < 0 ? 'left' : 'right';
    this.moving = true;
  }

  destroy(): void { this.sprite.destroy(); this.shadow.destroy(); this.bar.destroy(); this.tag?.destroy(); }

  private enter(s: AIState): void { this.ai = s; this.stateMs = 0; this.animMs = 0; }
  private startAttack(): void { this.enter('attack'); this.struck = false; this.gusted = false; this.sinceAttack = 0; }
  private gusted = false;
  /** A cloud creature's attack: a soft puff of wind blown forward (rolls out, swells and fades). */
  private blowGust(): void {
    const sc = this.scene, k = this.kin, d = this.dir === 'left' ? -1 : 1, S = this.kind.scale;
    if (!sc.textures.exists('mist-puff')) return;
    for (let i = 0; i < 3; i++) {
      const g = sc.add.image(k.x + d * 30 * S, k.y - k.z - 34 * S + (i - 1) * 8 * S, 'mist-puff').setDisplaySize(70 * S, 34 * S).setAlpha(0).setTint(0xfff6f0)
        .setDepth(actorDepth(k.x, k.y, k.z) + 0.2).setFlipX(d < 0);
      sc.tweens.add({ targets: g, x: g.x + d * (90 + i * 30) * S, alpha: { from: 0.9, to: 0 }, displayWidth: 130 * S, displayHeight: 54 * S, delay: i * 70, duration: 520, ease: 'Sine.easeOut', onComplete: () => g.destroy() });
    }
  }

  private homeBest = Infinity; private homeBestMs = 0; private lastBlocked = false;

  private canHit(w: MonsterWorld): boolean {
    if (!w.player.alive || w.player.z > 50) return false;
    const up = (w.player.level ?? 0) - this.homeZ;
    if (!(Math.abs(up) < 40 || (up >= 40 && up <= REACH_UP))) return false;   // he went up (or down) out of its reach meanwhile
    const vx = w.player.x - this.x, vy = w.player.y - this.y, d = Math.hypot(vx, vy), more = up >= 40 ? 34 : 0;
    if (d > this.kind.range + 6 + more + (up >= 40 ? 24 : 0) || Math.abs(vy) > 40 + (up >= 40 ? 30 : 0)) return false;
    if (d > 8 && (vx < 0) !== (this.dir === 'left')) return false; // in front of it
    return up >= 40 || clearLine(this.x, this.y, w.player.x, w.player.y, 30);   // up on a block: the block is no wall to its blade
  }

  private applyFrame(): void {
    let action: Action, i: number;
    const b = this.body;
    if (this.ai === 'dead') { action = 'death'; i = Math.min(C.actions.death - 1, Math.floor((this.stateMs * C.deathFps) / 1000)); }
    else if (b.state === 'launched') { action = 'hurt'; i = 1; }
    else if (b.state === 'knockdown') { action = 'death'; i = Math.min(4, 2 + Math.floor(this.kdMs / 90)); }
    else if (b.state === 'getup') { action = 'death'; i = Math.max(0, 3 - Math.floor(this.kdMs / 70)); }
    else if (b.state === 'hitstun' || b.hard.active(this.lastNow) || this.flashLeft > 0) { action = 'hurt'; i = this.flashLeft > C.hitFlashMs / 2 ? 0 : 1; }
    else if (this.ai === 'attack') {
      action = 'attack';
      const F = C.attackFrames, t = this.stateMs;
      if (t < WIND) i = Math.min(F.windup - 1, Math.floor(t / (WIND / F.windup)));
      else if (t < WIND + ACTIVE) i = F.windup;
      else i = F.windup + F.active + Math.min(F.recovery - 1, Math.floor((t - WIND - ACTIVE) / (RECOVER / F.recovery)));
    } else if (this.moving) { action = 'walk'; i = Math.floor((this.animMs * C.walkFps * (this.ai === 'wander' ? 0.7 : 1)) / 1000) % C.actions.walk; }
    else { action = 'idle'; i = Math.floor((this.animMs * C.idleFps) / 1000) % C.actions.idle; }
    if (b.state === 'getup' && this.kdMs > 280) { action = 'idle'; i = 0; }
    this.sprite.setTexture(mobFrameKey(this.kind.frames, this.dir, action, i));
  }

  private sync(): void {
    const k = this.kin, b = this.body, t = this.lastNow - b.lastHitAt, S = this.kind.scale;
    const away = this.hitFromX <= k.x ? 1 : -1;
    // Procedural reactions on top of the frame art: flinch lean + squash on every hit, tumble while juggled.
    let ang = 0, sx = 1, sy = 1;
    if (b.state === 'launched' && this.lastNow >= b.pinUntil) {
      const target = away * Math.min(1.45, 0.5 + this.airMs / 380);
      this.tumble += (target - this.tumble) * 0.25;
      ang = this.tumble + (t < 120 ? away * 0.25 * (1 - t / 120) : 0);
    } else {
      this.tumble *= 0.6;
      if (t < 150 && b.state !== 'knockdown' && b.state !== 'getup' && this.alive) { const p = 1 - t / 150; ang = away * 0.26 * p; sx = 1 + 0.1 * p; sy = 1 - 0.07 * p; }
      ang += this.tumble;
    }
    const H = 46 * S; // rotate around the body centre, not the feet
    const cx = k.x, cy = k.y - k.z - H;
    const T = this.kind.texQ ? 1 / this.kind.texQ : S;
    this.sprite.setRotation(ang).setScale(T * sx, T * sy).setPosition(cx - Math.sin(ang) * H, cy + Math.cos(ang) * H).setDepth(actorDepth(k.x, k.y, k.z));
    if (this.ai === 'dead') this.sprite.setAlpha(this.deathFade).setVisible(this.deathFade > 0);
    this.pos = { x: this.sprite.x, y: this.sprite.y };
    const h = Math.max(0, k.z - k.supportZ), s = Math.max(0.4, 1 - h / 140);
    this.shadow.setPosition(k.x, k.y - k.supportZ - 2).setDepth(actorDepth(k.x, k.y, k.supportZ) - 0.5).setVisible(this.alive).setScale(s);
    // HP bar over the head for a few seconds after a hit (MapleStory style)
    const show = this.alive && this.lastNow < this.barShowUntil;
    this.bar.setVisible(show);
    if (show && this.kind.level !== undefined) { // its level and name over the bar, coloured by how it compares to him (MapleStory)
      this.tag ??= this.scene.add.text(0, 0, '', { fontFamily: 'Inter, Arial, sans-serif', fontSize: '11px', fontStyle: '700', stroke: '#000000', strokeThickness: 3 }).setOrigin(0.5, 1).setResolution(2);
      const d = this.kind.level - this.charLevel, col = d >= 5 ? '#ff6a5a' : d >= 2 ? '#ffb35a' : d <= -5 ? '#9aa3b2' : '#ffffff';
      this.tag.setText(`Lv.${this.kind.level} ${this.kind.name}`).setColor(col).setPosition(k.x, k.y - k.z - 104 * S - 5).setDepth(NAME_DEPTH + k.y * 0.001).setVisible(true);
    } else this.tag?.setVisible(false);
    if (show) {
      const w = 54, y = k.y - k.z - 104 * S, x = k.x - w / 2, f = Math.max(0, this.hp / this.maxHp);
      this.bar.clear().setDepth(NAME_DEPTH + k.y * 0.001); // over blocks and urns in front
      this.bar.fillStyle(0x000000, 0.7).fillRoundedRect(x - 2, y - 2, w + 4, 9, 3);
      this.bar.fillStyle(0x3a0d0d, 1).fillRect(x, y, w, 5);
      this.bar.fillStyle(f > 0.35 ? 0xe8433a : 0xff7a2a, 1).fillRect(x, y, w * f, 5);
    }
  }
}
