import Phaser from 'phaser';
import { CHARACTER_CREATE as L, COLORS, DESIGN } from '../config/layout';
import { CharacterCreateUI, CreateLook, FIRST_LOOK } from '../ui/CharacterCreateUI';
import { lookFiles, lookIconLayers, lookIcons, queueLayers } from '../characters/LookArt';
import { toneTexture } from '../characters/Skin';
import MENU_LOOK from '../data/menu-look.json';
import { HERO3D } from '../arena3d/hero3dFlag';
import type { HeroPreview3D } from '../arena3d/HeroPreview3D';
import { BASE_V3, isV3 } from '../characters/baseSet';
import V3_MENU from '../data/v3-menu-look.json';

/** The new character on the pedestal, dressed as chosen: back hair, the bare body in its skin tone, the face, the starter
 *  gear it will wear (pants, boots, shirt in their colours, the sword in hand), the forehead between the bangs, the hair
 *  over the head — one image each, all on the menu canvas (tools/base/naked_frames.py). The face and hairstyle
 *  buttons are pictures of this same look, redrawn with every choice. */
const FIT = { ...MENU_LOOK, ...(BASE_V3 ? V3_MENU : {}) } as Record<string, { fit: number }>;   // (the rebuild's base: its own canvas)
/** The new Beginner, painted like the ready heroes (one picture per body; a body without one still shows the old base). */
const BEGINNER_ART: Record<string, string> = { male: 'assets/final/heroes/beginner/male.png', female: 'assets/final/heroes/beginner/female.png' };

// Background, pedestal and the dressed preview; all UI lives in CharacterCreateUI (DOM overlay).
export class CharacterCreateScene extends Phaser.Scene {
  private ui?: CharacterCreateUI;

  constructor() { super('CharacterCreateScene'); }

  preload(): void {
    queueLayers(this, [...lookFiles(FIRST_LOOK), ...lookIconLayers(FIRST_LOOK)]); // the first look shown and its buttons
    for (const g of Object.keys(BEGINNER_ART)) this.load.image(`beginner.${g}`, BEGINNER_ART[g]);
  }

  create(): void {
    const bg = this.add.image(DESIGN.width / 2, DESIGN.height / 2, 'characterSelect.background');
    bg.setScale(Math.max(DESIGN.width / bg.width, DESIGN.height / bg.height));

    const P = L.preview;
    const g = this.add.graphics();
    g.fillStyle(0x05080d, 0.5).fillEllipse(P.centerX, P.pedestalY, P.rx * 2, P.ry * 2);
    g.lineStyle(1.5, COLORS.gold, 0.45).strokeEllipse(P.centerX, P.pedestalY, P.rx * 2, P.ry * 2);

    // The new character: the clean base, dressed in the starter outfit with the chosen face, hair, skin and colours.
    const layers: Phaser.GameObjects.Image[] = [];
    let want: CreateLook = FIRST_LOOK, ver = 0;
    const art = this.add.image(P.centerX, P.pedestalY + 8, '__DEFAULT').setOrigin(0.5, 1).setVisible(false);
    // the 3D Beginner (David 24 Oct: the heroes in 3D; the painted ones go): the chosen body, man or woman, standing on
    // the pedestal with the Beginner's sword (each loaded once, the other hidden)
    const pv3: Record<string, HeroPreview3D> = {}, loading3 = new Set<string>();
    const show3D = (gender: string) => {
      for (const [g2, p] of Object.entries(pv3)) p.image.setVisible(g2 === gender);
      if (pv3[gender] || loading3.has(gender)) return;
      loading3.add(gender);
      void import('../arena3d/HeroPreview3D').then(async ({ HeroPreview3D }) => {
        const p = await HeroPreview3D.create(this, { female: gender === 'female', weapon: 'sword', key: `hero-preview-3d-${gender}`, w: 440, h: 680 });
        if (!this.sys.isActive()) { p.destroy(); return; }
        p.image.setPosition(P.centerX, P.pedestalY + 8).setScale((P.height * 0.86) / (680 / (1.08 * 1.02)) / HeroPreview3D.RES);
        pv3[gender] = p; p.image.setVisible(want.gender === gender);
      });
    };
    const apply = (v: number) => {
      if (v !== ver) return; // a newer choice is on its way
      const l = want;
      if (HERO3D.on && !isV3(l.gender)) { art.setVisible(false); layers.forEach((im) => im.setVisible(false)); show3D(l.gender); const icons = lookIcons(this, l); if (icons) this.ui?.setIcons(icons); return; }
      if (this.textures.exists(`beginner.${l.gender}`) && !isV3(l.gender)) { // the painted Beginner on the pedestal (the rebuild's base: its look)
        art.setTexture(`beginner.${l.gender}`).setVisible(true);
        art.setScale((P.height * 0.86) / art.height);
        layers.forEach((im) => im.setVisible(false));
        return;
      }
      art.setVisible(false);
      const files = lookFiles(l);
      const keys = files.map(([k, , toned]) => (toned ? toneTexture(this, k, l.skin) : this.textures.exists(k) ? k : null));
      if (keys.some((k) => !k)) return; // the rest still loading
      const s = (P.height * 0.84) / FIT[l.gender].fit; // sized by the figure (the canvas has room above for the hair)
      while (layers.length < keys.length) layers.push(this.add.image(P.centerX, P.top + P.height, '__DEFAULT').setOrigin(0.5, 1));
      layers.forEach((im, i) => { if (i < keys.length) im.setTexture(keys[i]!).setScale(s).setVisible(true); else im.setVisible(false); });
      const icons = lookIcons(this, l);
      if (icons) this.ui?.setIcons(icons);
    };
    const dress = (l: CreateLook) => {
      want = l; const v = ++ver;
      if (!queueLayers(this, [...lookFiles(l), ...lookIconLayers(l)])) { apply(v); return; }
      this.load.once(Phaser.Loader.Events.COMPLETE, () => apply(v));
      if (!this.load.isLoading()) this.load.start();
    };

    this.ui = new CharacterCreateUI(this.game.canvas.parentElement!, this.game.canvas, {
      onBack: () => this.scene.start('CharacterSelectScene'),
      onCreated: () => this.scene.start('CharacterSelectScene'),
      onLookChange: dress,
    });
    apply(ver); // the buttons' pictures (the first look was dressed before the panel existed)
    this.events.on(Phaser.Scenes.Events.POST_UPDATE, () => this.ui?.layout());
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.events.off(Phaser.Scenes.Events.POST_UPDATE);
      this.ui?.destroy();
      this.ui = undefined;
    });
  }
}
